# ! [doc = " Windows-specific extensions to primitives in the [`std::ffi`] module."] # ! [doc = ""] # ! [doc = " # Overview"] # ! [doc = ""] # ! [doc = " For historical reasons, the Windows API uses a form of potentially"] # ! [doc = " ill-formed UTF-16 encoding for strings. Specifically, the 16-bit"] # ! [doc = " code units in Windows strings may contain [isolated surrogate code"] # ! [doc = " points which are not paired together][ill-formed-utf-16]. The"] # ! [doc = " Unicode standard requires that surrogate code points (those in the"] # ! [doc = " range U+D800 to U+DFFF) always be *paired*, because in the UTF-16"] # ! [doc = " encoding a *surrogate code unit pair* is used to encode a single"] # ! [doc = " character. For compatibility with code that does not enforce"] # ! [doc = " these pairings, Windows does not enforce them, either."] # ! [doc = ""] # ! [doc = " While it is not always possible to convert such a string losslessly into"] # ! [doc = " a valid UTF-16 string (or even UTF-8), it is often desirable to be"] # ! [doc = " able to round-trip such a string from and to Windows APIs"] # ! [doc = " losslessly. For example, some Rust code may be \"bridging\" some"] # ! [doc = " Windows APIs together, just passing `WCHAR` strings among those"] # ! [doc = " APIs without ever really looking into the strings."] # ! [doc = ""] # ! [doc = " If Rust code *does* need to look into those strings, it can"] # ! [doc = " convert them to valid UTF-8, possibly lossily, by substituting"] # ! [doc = " invalid sequences with [`U+FFFD REPLACEMENT CHARACTER`][U+FFFD], as is"] # ! [doc = " conventionally done in other Rust APIs that deal with string"] # ! [doc = " encodings."] # ! [doc = ""] # ! [doc = " # `OsStringExt` and `OsStrExt`"] # ! [doc = ""] # ! [doc = " [`OsString`] is the Rust wrapper for owned strings in the"] # ! [doc = " preferred representation of the operating system. On Windows,"] # ! [doc = " this struct gets augmented with an implementation of the"] # ! [doc = " [`OsStringExt`] trait, which has an [`OsStringExt::from_wide`] method. This"] # ! [doc = " lets you create an [`OsString`] from a `&[u16]` slice; presumably"] # ! [doc = " you get such a slice out of a `WCHAR` Windows API."] # ! [doc = ""] # ! [doc = " Similarly, [`OsStr`] is the Rust wrapper for borrowed strings from"] # ! [doc = " preferred representation of the operating system. On Windows, the"] # ! [doc = " [`OsStrExt`] trait provides the [`OsStrExt::encode_wide`] method, which"] # ! [doc = " outputs an [`EncodeWide`] iterator. You can [`collect`] this"] # ! [doc = " iterator, for example, to obtain a `Vec<u16>`; you can later get a"] # ! [doc = " pointer to this vector's contents and feed it to Windows APIs."] # ! [doc = ""] # ! [doc = " These traits, along with [`OsString`] and [`OsStr`], work in"] # ! [doc = " conjunction so that it is possible to **round-trip** strings from"] # ! [doc = " Windows and back, with no loss of data, even if the strings are"] # ! [doc = " ill-formed UTF-16."] # ! [doc = ""] # ! [doc = " [ill-formed-utf-16]: https://simonsapin.github.io/wtf-8/#ill-formed-utf-16"] # ! [doc = " [`collect`]: crate::iter::Iterator::collect"] # ! [doc = " [U+FFFD]: crate::char::REPLACEMENT_CHARACTER"] # ! [doc = " [`std::ffi`]: crate::ffi"] # ! [stable (feature = "rust1" , since = "1.0.0")] use split_decls_genesis :: ourprelude :: * ; use alloc :: wtf8 :: Wtf8Buf ; use crate :: ffi :: { OsStr , OsString } ; use crate :: fmt ; use crate :: iter :: FusedIterator ; use crate :: sealed :: Sealed ; use crate :: sys :: os_str :: Buf ; use crate :: sys_common :: { AsInner , FromInner } ; #[doc = " Windows-specific extensions to [`OsString`]."] #[doc = ""] #[doc = " This trait is sealed: it cannot be implemented outside the standard library."] #[doc = " This is so that future additional methods are not breaking changes."] #[stable (feature = "rust1" , since = "1.0.0")] pub trait OsStringExt : Sealed { #[doc = " Creates an `OsString` from a potentially ill-formed UTF-16 slice of"] #[doc = " 16-bit code units."] #[doc = ""] #[doc = " This is lossless: calling [`OsStrExt::encode_wide`] on the resulting string"] #[doc = " will always return the original code units."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::ffi::OsString;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " // UTF-16 encoding for \"Unicode\"."] #[doc = " let source = [0x0055, 0x006E, 0x0069, 0x0063, 0x006F, 0x0064, 0x0065];"] #[doc = ""] #[doc = " let string = OsString::from_wide(&source[..]);"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] fn from_wide (wide : & [u16]) -> Self ; } #[stable (feature = "rust1" , since = "1.0.0")] impl OsStringExt for OsString { fn from_wide (wide : & [u16]) -> OsString { FromInner :: from_inner (Buf { inner : Wtf8Buf :: from_wide (wide) }) } } #[doc = " Windows-specific extensions to [`OsStr`]."] #[doc = ""] #[doc = " This trait is sealed: it cannot be implemented outside the standard library."] #[doc = " This is so that future additional methods are not breaking changes."] #[stable (feature = "rust1" , since = "1.0.0")] pub trait OsStrExt : Sealed { #[doc = " Re-encodes an `OsStr` as a wide character sequence, i.e., potentially"] #[doc = " ill-formed UTF-16."] #[doc = ""] #[doc = " This is lossless: calling [`OsStringExt::from_wide`] and then"] #[doc = " `encode_wide` on the result will yield the original code units."] #[doc = " Note that the encoding does not add a final null terminator."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " use std::ffi::OsString;"] #[doc = " use std::os::windows::prelude::*;"] #[doc = ""] #[doc = " // UTF-16 encoding for \"Unicode\"."] #[doc = " let source = [0x0055, 0x006E, 0x0069, 0x0063, 0x006F, 0x0064, 0x0065];"] #[doc = ""] #[doc = " let string = OsString::from_wide(&source[..]);"] #[doc = ""] #[doc = " let result: Vec<u16> = string.encode_wide().collect();"] #[doc = " assert_eq!(&source[..], &result[..]);"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] fn encode_wide (& self) -> EncodeWide < '_ > ; } #[stable (feature = "rust1" , since = "1.0.0")] impl OsStrExt for OsStr { #[inline] fn encode_wide (& self) -> EncodeWide < '_ > { EncodeWide { inner : self . as_inner () . inner . encode_wide () } } } #[doc = " Iterator returned by [`OsStrExt::encode_wide`]."] #[stable (feature = "rust1" , since = "1.0.0")] #[derive (Clone)] pub struct EncodeWide < 'a > { inner : alloc :: wtf8 :: EncodeWide < 'a > , } #[stable (feature = "encode_wide_debug" , since = "1.91.0")] impl fmt :: Debug for EncodeWide < '_ > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { fmt :: Debug :: fmt (& self . inner , f) } } #[stable (feature = "rust1" , since = "1.0.0")] impl Iterator for EncodeWide < '_ > { type Item = u16 ; #[inline] fn next (& mut self) -> Option < u16 > { self . inner . next () } #[inline] fn size_hint (& self) -> (usize , Option < usize >) { self . inner . size_hint () } } #[stable (feature = "encode_wide_fused_iterator" , since = "1.62.0")] impl FusedIterator for EncodeWide < '_ > { }